def test_conjugate_verb_regular_present():
    result = conjugate_verb("hablar", "present")
    assert "hablo" in result
    assert "hablas" in result
    assert "habla" in result
    assert "hablamos" in result
    assert "habláis" in result
    assert "hablan" in result
    assert "regular pattern" in result

def test_conjugate_verb_irregular_present():
    result = conjugate_verb("ser", "present")
    assert "soy" in result
    assert "eres" in result
    assert "es" in result
    assert "somos" in result
    assert "sois" in result
    assert "son" in result
    assert "irregular forms" in result

def test_conjugate_verb_future():
    result = conjugate_verb("hablar", "future")
    assert "hablaré" in result
    assert "hablarás" in result
    assert "hablará" in result
    assert "hablaremos" in result
    assert "hablaréis" in result
    assert "hablarán" in result
