def test_save_flashcards_empty_deck():
    result = save_flashcards("empty deck", [])
    assert "No cards were provided, so nothing was saved." in result

def test_save_flashcards_valid_deck():
    cards = [{"spanish": "la casa", "english": "the house"}, {"spanish": "el coche", "english": "the car"}]
    result = save_flashcards("house and car", cards)
    assert "Saved 2 cards" in result
    assert latest_deck() is not None
    assert latest_deck().name == "house_and_car.csv"

def test_save_flashcards_invalid_cards():
    cards = [{"spanish": "la casa"}, {"english": "the car"}]
    result = save_flashcards("house and car", cards)
    assert "Every card was missing a Spanish or an English side" in result

def test_save_flashcards_too_many_cards():
    cards = [{"spanish": f"la casa {i}", "english": f"the house {i}"} for i in range(MAX_CARDS + 1)]
    result = save_flashcards("too many cards", cards)
    assert f"That is {MAX_CARDS + 1} cards" in result
